export const title = "How to Fit a Document Camera and a Full Page on a Small Desk";
export const metaTitle = "Document Camera Setup on a Small Desk";
export const metaDescription = "Plan a document-camera setup around actual page coverage, camera height, hand clearance, lighting, software, and a pack-away routine.";
